import { ChefHat} from "lucide-react";

function Header() {
  return (
    <header className="bg-white/80 backdrop-blur border-b">
      <div className="max-w-7xl mx-auto px-6 h-20 flex flex-row items-center relative ">

        {/* Left div */}
        <div className="absolute left-6">
          <div className="w-6 h-6 bg-gray-700 rounded-full"></div>
          <ChefHat/>
        </div>

        {/* Center div */}
        <div className="mx-auto">
          <h1 className="text-2xl font-semibold">ChefGPT</h1>
        </div>

        {/* Right div */}
        <div className="absolute right-6">
          <div className="w-6 h-6 bg-gray-700 rounded-full"><ChefHat/></div>
        </div>

      </div>
    </header>
  );
}

export default Header;
